// Browser front end mirrors research/features.py. No microphone or network access.
export const SR=16000;
function fftPower(frame){const n=512,r=new Float64Array(n),im=new Float64Array(n);for(let i=0;i<400;i++)r[i]=frame[i]*(.54-.46*Math.cos(2*Math.PI*i/399));for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j){let t=r[i];r[i]=r[j];r[j]=t;}}for(let len=2;len<=n;len*=2){let a=-2*Math.PI/len,wr0=Math.cos(a),wi0=Math.sin(a);for(let i=0;i<n;i+=len){let wr=1,wi=0;for(let j=0;j<len/2;j++){let u=i+j,v=u+len/2,tr=r[v]*wr-im[v]*wi,ti=r[v]*wi+im[v]*wr;r[v]=r[u]-tr;im[v]=im[u]-ti;r[u]+=tr;im[u]+=ti;let next=wr*wr0-wi*wi0;wi=wr*wi0+wi*wr0;wr=next;}}}return Array.from({length:257},(_,i)=>(r[i]*r[i]+im[i]*im[i])/512);}
const mel=f=>2595*Math.log10(1+f/700),hz=m=>700*(10**(m/2595)-1),pts=Array.from({length:28},(_,i)=>hz(mel(20)+(mel(8000)-mel(20))*i/27));
const banks=Array.from({length:26},(_,i)=>Array.from({length:257},(_,k)=>Math.max(0,Math.min((k*31.25-pts[i])/(pts[i+1]-pts[i]),(pts[i+2]-k*31.25)/(pts[i+2]-pts[i+1])))));
const dct=Array.from({length:13},(_,k)=>Array.from({length:26},(_,j)=>Math.cos(Math.PI*k*(j+.5)/26)*Math.sqrt((k===0?1:2)/26)));
const sum=a=>a.reduce((s,v)=>s+v,0),dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0);
export function frequencyMap(wave,maxColumns=72){if(!wave?.length)return {bands:26,columns:0,values:[],minHz:20,maxHz:8000};let mean=0;for(const v of wave){if(!Number.isFinite(v))throw Error('Invalid audio samples.');mean+=v;}mean/=wave.length;const x=Float64Array.from(wave,v=>v-mean);let peak=1e-8;for(const v of x)peak=Math.max(peak,Math.abs(v));for(let i=0;i<x.length;i++)x[i]/=peak;const frames=Math.max(0,Math.floor((x.length-400)/160)+1),group=Math.max(1,Math.ceil(frames/maxColumns)),raw=[];for(let first=0;first<frames;first+=group){const energies=new Float64Array(26);let count=0;for(let fi=first;fi<Math.min(frames,first+group);fi++){const p=fftPower(x.subarray(fi*160,fi*160+400));for(let b=0;b<26;b++)energies[b]+=Math.log10(Math.max(dot(p,banks[b]),1e-12));count++;}raw.push(Array.from(energies,v=>v/count));}const flat=raw.flat(),lo=Math.min(...flat),hi=Math.max(...flat),span=Math.max(1e-9,hi-lo),values=raw.map(col=>col.map(v=>(v-lo)/span));return {bands:26,columns:values.length,values,minHz:20,maxHz:8000};}
function delta(a){return a.map((row,t)=>row.map((_,k)=>{const at=i=>a[Math.max(0,Math.min(a.length-1,i))][k];return (at(t+1)-at(t-1)+2*(at(t+2)-at(t-2)))/10;}));}
function stats(a){const mean=a[0].map((_,k)=>a.reduce((s,r)=>s+r[k],0)/a.length),sd=mean.map((m,k)=>Math.sqrt(a.reduce((s,r)=>s+(r[k]-m)**2,0)/a.length));return [...mean,...sd];}
export function features(wave){if(wave.length<400)throw Error('Audio is too short.');let mean=0;for(const v of wave){if(!Number.isFinite(v))throw Error('Invalid audio samples.');mean+=v;}mean/=wave.length;const x=Float64Array.from(wave,v=>v-mean);let peak=1e-8;for(const v of x)peak=Math.max(peak,Math.abs(v));for(let i=0;i<x.length;i++)x[i]/=peak;const mf=[],ex=[];for(let start=0;start+400<=x.length;start+=160){const frame=x.subarray(start,start+400),p=fftPower(frame),total=sum(p)+1e-12;const lm=banks.map(b=>Math.log(Math.max(dot(p,b),1e-12)));mf.push(dct.map(d=>dot(lm,d)));let cent=0;for(let k=0;k<p.length;k++)cent+=p[k]*k*31.25;cent/=total;let width=0,logs=0,cum=0,roll=0,found=false;for(let k=0;k<p.length;k++){width+=p[k]*(k*31.25-cent)**2;logs+=Math.log(p[k]+1e-12);cum+=p[k];if(!found&&cum>=.85*total){roll=k*31.25;found=true;}}let z=0,rms=0;for(let k=0;k<400;k++){rms+=frame[k]**2;if(k&&(frame[k]>=0)!==(frame[k-1]>=0))z++;}ex.push([z/399,cent/8000,Math.sqrt(width/total)/8000,roll/8000,Math.exp(logs/257)/(sum(p)/257+1e-12),Math.sqrt(rms/400)]);}const d=delta(mf),dd=delta(d);return [...stats(mf),...stats(d),...stats(dd),...stats(ex)];}
export function decision(f,m){const z=f.map((v,i)=>(v-m.mean[i])/m.scale[i]);let score=m.intercept;for(let j=0;j<m.support.length;j++){let distance=0;for(let i=0;i<z.length;i++)distance+=(z[i]-m.support[j][i])**2;score+=m.dual[j]*Math.exp(-m.gamma*distance);}return {score,distance:dot(z,z)/z.length};}
export function predict(wave,m){const f=features(wave),d=decision(f,m);return {...d,probability:1/(1+Math.exp(-Math.max(-50,Math.min(50,m.calibration.slope*d.score+m.calibration.intercept))))};}
export function quality(wave){let sq=0,clip=0,peak=0;for(const x of wave){if(!Number.isFinite(x))throw Error('Audio contains invalid samples.');sq+=x*x;peak=Math.max(peak,Math.abs(x));if(Math.abs(x)>=.999)clip++;}return {rms:Math.sqrt(sq/wave.length),clipping:clip/wave.length,peak,duration:wave.length/SR};}
export function analyze(wave,m){const q=quality(wave);if(q.duration<2)throw Error('Use at least 2 seconds of speech.');if(q.duration>60.05)throw Error('Use a recording no longer than 60 seconds.');if(q.rms<1e-4)throw Error('No usable audio was found. Choose a recording with audible speech.');const whole=predict(wave,m),windows=[];for(let start=0;start+32000<=wave.length;start+=16000){const r=decision(features(wave.subarray(start,start+32000)),m);windows.push({start:start/SR,end:(start+32000)/SR,score:r.score});}const warnings=[];let label=whole.probability<=m.thresholds.real?'real':whole.probability>=m.thresholds.fake?'fake':'uncertain';if(q.clipping>.1){label='uncertain';warnings.push('Heavy clipping: the recording may be distorted.');}if(q.duration<3){label='uncertain';warnings.push('Very short recording: limited speech context.');}if(whole.distance>m.ood_limit){label='uncertain';warnings.push('Acoustic features differ markedly from training audio. Confidence may not transfer.');}return {label,probability:whole.probability,rawScore:whole.score,quality:q,warnings,windows,modelVersion:m.version};}
